LuaFunction.Formula:
function JBTEH_MAS_nonPortalPole_code()
	local entireKm = math.floor(ReferenceMileage / 1000)
	return string.format("%d-%02d", entireKm, Seq), _info("Pole's code is inherited from reference mileage (" .. ReferenceMileage .. ") and the local variable Seq (" .. Seq .. ").")
end

function _JBTEH_MAS_getSpanlengths() --[[ This function assumes that wtb and cnt are chained with a common previous/next relation. Also handles wtb mounted on a tunnel wall baseplate. - Start at OCS pole and find its cantilevers and wtb's, or start at tunnel wall baseplate and find its wtb. - Iterate over all such objects found, locate the next cantilever or wtb in sequence - For each next object, store next object's contact wire name and the straight-line 2D distance in the XY plane from CW wireclamp/wtb to CW wireclamp/wtb. Return value: A collection of collections, each containing the 'name' of a contact wire and the straight-line 2D distance to next sl. --]] local tol = 1.0 --[m] Tolerance when searching for wire tension balancers at an OCS pole local result = {}
--Find all cantilevers and WTBs at this OCS pole, but skip WTBs serving midpoint anchor lines or AT conductors, earthing wires etc: local rCnt = getRelatedObjects(rel_OcsPole_Has_Cantilever) local rWtb = getNearbyPointObjects2D(tol, rctype_WireTensioningBalancer) :filter(function (x) return x.Alignment.RcType == rctype_ContactWire end) local items = getUnionOfCollections({rCnt, rWtb}) local nItems = getCollectionLength(items)
if nItems == 0 then --Poles for supporting OCS portals will exist, with neither wtbs nor cantilevers at the pole. return {}, _info("No spanlengthItems") else for i = 0, nItems - 1 do local thisItem = items[i] local cowName local p1 if thisItem.RcType == rctype_WireTensioningBalancer then p1 = thisItem:getPoint3D() cowName = thisItem.Alignment.name else --thisItem.RcType == rctype_Cantilever: p1 = thisItem:NOBN_ocs_getWireClampPoint3D() cow, nCow = thisItem:getRelatedObjects(rel_Cantilever_Holds_ContactWire) if nCow == 0 then --Cantilever has no relation to its contact wire yet: cowName = "L?" else cowName = cow[0].name end end local nextItems, nNextItems = thisItem:getRelatedObjects(rel_CantileverOrWtb_HasNext_CantileverOrWtb) --A WTB might be the terminal for a contact wire (at a buffer stop etc). Treat only those who possess a successor: if nNextItems > 0 then local nextItem = nextItems[0] local p2 if nextItem.RcType == rctype_WireTensioningBalancer then p2 = nextItem:getPoint3D() else --nextItem.RcType == rctype_Cantilever: p2 = nextItem:NOBN_ocs_getWireClampPoint3D() end local distance2D = RC__getDistance2D(p1, p2) table.insert(result, {Spanlength = RC__round(distance2D, 1), Wirename = cowName}) end end end return result, _info(getCollectionLength(result) .. " spanlength(s)") end

function _JBTEH_MAS_VerticalOffset()
	return 0
end

function _JBTEH_MAS_ocsPole_AngularOffset() local pRelationName = rel_OcsPole_IsSupportFor_OcsPortal local pr, pn = getRelatedObjects(pRelationName) if pn == 0 then return getPropertyValue("AngularOffset"), _info("No control input - adjust angular offset manually or relate with '" .. pRelationName .. "' to a portal (which has second support pole).")
else local portal = pr[0] local s = rel_OcsPortal_IsSupportedBy_OcsPole local r, n = getRelatedObjects(s, portal)
if n == 0 then return getPropertyValue("AngularOffset"), _error, _info("ERROR OCS pole has bad connection to gantry '" .. RC__identify(portal) .. "'.")
elseif n == 1 then --Gantry: return getPropertyValue("AngularOffset"), _info("OCS pole is connected to a gantry '" .. RC__identify(portal) .. "' - adjust pole's angular offset manually or change gantry into portal (which has one more portal support poles).")
elseif n == 2 then --Assume that the first two related poles are located at the portal's extremities: local m1 = r[0] local m2 = r[1] local x1 = m1.geoCoord.X local y1 = m1.geoCoord.Y local x2 = m2.geoCoord.X local y2 = m2.geoCoord.Y local portalDir = math.deg(math.atan(y2 - y1, x2 - x1)) % 180.0 local tg = getAlignmentInfo().Tangent local trackDir = math.deg(math.atan(tg.Y, tg.X)) local info = "Angular Offset deduced using portal support poles '" .. RC__identify(m1) .. "' and '" .. RC__identify(m2) .. "'." return (360.0 + RC__round(90 - (trackDir - portalDir), 3)) % 360.0, _info(info)
else --TODO: Locate the two support poles at each end of portal, use this to find angular offset, then turn yourself if you --are a support pole at one or the other end, or just adapt if you are in between ends. return getPropertyValue("AngularOffset"), _info("OCS pole is connected to a portal '" .. RC__identify(portal) .. " with total 3 or more supporting poles" .. "' - adjust pole's angular offset manually.") end end end

