LuaFunction.Formula:
function _JBTEH_MAS_DropArmUnderPortal_AngularOffset() local ps = rel_OcsPole_IsDropArmUnder_OcsPortal local pr, pn = getRelatedObjects(ps) if pn == 0 then return getPropertyValue("AngularOffset"), _info("UNFINISHED - relate drop arm to portal with '" .. ps .. "'.")
else local portal = pr[0] local s = rel_OcsPortal_IsSupportedBy_OcsPole local r, n = getRelatedObjects(s, portal)
if n == 0 then return getPropertyValue("AngularOffset"), _error, _info("ERROR Drop arm has bad connection to gantry '" .. RC__identify(portal) .. "'.")
elseif n == 1 then --Gantry: return getPropertyValue("AngularOffset"), _info("DropArm is connected to a gantry '" .. RC__identify(portal) .. "' - adjust drop arm's angular offset manually or change gantry into portal (which has one more portal support pole).")
elseif n == 2 then --Assume that the first two related poles are located at the portal's extremities: local p1 = r[0] local p2 = r[1] local x1 = p1.geoCoord.X local y1 = p1.geoCoord.Y local x2 = p2.geoCoord.X local y2 = p2.geoCoord.Y local portalDir = math.deg(math.atan(y2 - y1, x2 - x1)) % 180.0 local tg = getAlignmentInfo().Tangent local trackDir = math.deg(math.atan(tg.Y, tg.X)) local info = "Angular Offset deduced using portal support poles '" .. RC__identify(p1) .. "' and '" .. RC__identify(p2) .. "'." return (360.0 + RC__round(90 - (trackDir - portalDir), 3)) % 360.0, _info(info)
else --TODO: Locate the two support poles at each end of portal, uses this to find angular offset, then turn yourself if you --are a support pole at one or the other end, or just adapt if you are in between ends. return getPropertyValue("AngularOffset"), _info("DropArm is connected to a portal '" .. RC__identify(portal) .. " with total 3 or more supporting poles" .. "' - adjust pole's angular offset manually.") end end end

function _JBTEH_MAS_DropArmUnderPortal_Geometry3DName()
	return "NO-BN-3D-EH-MAS-HENGEMAST-I-ÅK-HUP-" .. (OcsPoleCrossSection:match("(%d+x%d+)")) .. "-" .. OcsPoleHeight
end

